window.docContents[17].resolve({"/Aula-1___-Motiva______o-e-L___gica-Proposicional/#aula-1":{"contents":"Esta aula motiva a verificação formal de software e revisa a lógica proposicional, seguindo o capítulo 1 de How To Prove It with Lean (HTPIwL). Ela apresenta os conectivos, as equivalências clássicas, as regras de dedução natural, a sua codificação em Lean como termos de prova e as provas com táticas.\n\nEsta aula também está disponível como slides de apresentação.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Verificação Formal de Software","header":"1. Aula 1: Motivação e Lógica Proposicional","id":"/Aula-1___-Motiva______o-e-L___gica-Proposicional/#aula-1"}});